import re
from datetime import datetime

with open('news/index.html', 'r') as f:
    content = f.read()

# Find all news items using the full article block
article_pattern = r'(<article class=\"news-item\">.*?</article>)'
articles = re.findall(article_pattern, content, re.DOTALL)

print(f'Found {len(articles)} article blocks')

# Extract date and title from each
def extract_info(article):
    date_match = re.search(r'<span class=\"news-date\">([^<]+)</span>', article)
    href_match = re.search(r'<a href=\"([^\"]+)\">([^<]+)</a>', article)
    if date_match and href_match:
        date_str = date_match.group(1)
        href = href_match.group(1)
        title = href_match.group(2).strip()
        return (date_str, href, title, article)
    return None

parsed = [extract_info(a) for a in articles]
parsed = [p for p in parsed if p]

# Parse dates for sorting
def parse_date(date_str):
    try:
        return datetime.strptime(date_str, '%B %d, %Y')
    except:
        return datetime.min

# Sort by date descending
def sort_key(p):
    return parse_date(p[0])

parsed.sort(key=sort_key, reverse=True)

print()
print('Sorted articles (newest first):')
for date, href, title, _ in parsed[:10]:
    print(f'  {date}: {title[:50]}...')
""}

